_SIMPLE = [("Balingkinitan siya.", "He is slender."), ("Pandak ang madrasta ko.", "My stepmother is short."), ("Kayumanggi ang kulay ng balat niya.", "Her skin complexion is brown."), ("Itim at kulot ang buhok niya.", "Her hair is black and curly."), ("Singkit siya.", "She has slanted eyes."), ("Pango siya.", "She has a flat nose.")]
